// Block (composition) — a responsive product preview inside the Dialog Component.
// Dialog owns modal behavior and chrome; Gallery owns image selection.
import type { ReactNode } from "react";
import { Button } from "../components/Button";
import { DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "../components/Dialog";
import { Stack } from "../layouts/Stack";
import { Gallery, type GalleryProps } from "./Gallery";
import "./QuickView.css";

export interface QuickViewProps {
  trigger: ReactNode;
  title: string;
  price: string;
  description?: ReactNode;
  images: GalleryProps["images"];
  onAddToCart?: () => void;
  addLabel?: string;
}

export function QuickView({
  trigger,
  title,
  price,
  description,
  images,
  onAddToCart,
  addLabel = "Add to cart",
}: QuickViewProps) {
  return (
    <DialogTrigger>
      {trigger}
      <DialogContent width="large" className="sd-quickview"
        header={
          <DialogHeader>
            <DialogTitle>{title}</DialogTitle>
          </DialogHeader>
        }
      >
        <Stack direction={{ small: "column", medium: "row" }} gap="large" className="sd-quickview__layout">
          <div className="sd-quickview__gallery">
            <Gallery images={images} layout="showcase" />
          </div>
          <Stack gap="small" className="sd-quickview__details">
            {/* Name and price are ONE unit, at a tighter rung than the panel's own — the pair
                `ProductCard` already groups. Flat, the same 12px separated the name from its
                price as separated the price from the description below it. */}
            <>
              <Stack gap="2x-small" className="sd-quickview__header">
                <p className="sd-quickview__title sd-type-title-medium">{title}</p>
                <p className="sd-quickview__price sd-type-body-medium-emphasized">{price}</p>
              </Stack>
            </>
            {description && (
              <>
                <div className="sd-quickview__description sd-type-body-medium">{description}</div>
              </>
            )}
            {/* usage: completing-action — adding to the cart is the task the quick view exists for, not a submit */}
            <Button variant="primary" size="large" onPress={onAddToCart}>
              {addLabel}
            </Button>
          </Stack>
        </Stack>
      </DialogContent>
    </DialogTrigger>
  );
}

/* QuickView.css — .sd-quickview (Block)
   Arrangement only: splits gallery and product details at the shared responsive breakpoint. */
.sd-quickview__gallery,
.sd-quickview__details {
  min-width: 0;
  flex: 1 1 0;
}

.sd-quickview__title,
.sd-quickview__price {
  margin: 0;
}

.sd-quickview__description {
  color: var(--sd-color-text-muted);
  width: 100%;
}
